contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        // Precondition: caller is a distinct address from the test contract (if it is the test contract, it is the owner).
        require(caller != address(this));

        // Determine whether the caller is currently the owner.
        address ownerBefore = c.owner();
        bool isOwner = caller == ownerBefore;

        // Make the deciding call as the given caller using a low-level call so we can
        // control msg.sender without needing a helper function.
        (bool success, bytes memory returndata) = address(c).call(
            abi.encodeWithSignature("setOwner(address)", newOwner)
        );

        // Decode the returned success flag if the call succeeded.
        bool returnedSuccess = success && returndata.length >= 32 && abi.decode(returndata, (bool));

        // Read the owner after the call.
        address ownerAfter = c.owner();

        // General rule: caller can set owner to newOwner iff caller is the current owner.
        assert(
            (isOwner && success && returnedSuccess && ownerAfter == newOwner) ||
            (!isOwner && !success && ownerAfter == ownerBefore)
        );
    }
}

