    function run(address attacker, address newOwner) public {
        // ensure the caller (this contract) is not the owner for the attack attempt
        require(attacker != address(this), "attacker must not be the test contract");
        // the test contract deployed c and is the current owner
        require(c.owner() == address(this), "test contract must be the current owner");

        // first, make a successful owner change from the current owner (this contract)
        c.setOwner(newOwner);
        address ownerAfter = c.owner();

        // second, an attacker (not the owner) tries to change the owner
        bool reverted;
        try c.setOwner(attacker) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // the attacker's call must revert and the owner must remain the one set by the successful call
        assert(reverted && c.owner() == ownerAfter);
    }
}

